<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { ArrowLeft } from 'lucide-vue-next'; import AppShell from '@/components/AppShell.vue'; import { memoryService } from '@/services/memory-service'; import { useAppStore } from '@/stores/app';const route=useRoute(),router=useRouter(),app=useAppStore();const content=ref(''),loading=ref(false);onMounted(async()=>content.value=(await memoryService.get(String(route.params.id)))?.content??'');async function save(){loading.value=true;try{await memoryService.update(String(route.params.id),content.value);app.showToast('Memory diperbarui');router.push(`/memories/${route.params.id}`)}finally{loading.value=false}}</script>
<template><AppShell><div class="page"><button class="icon-button -ml-3" aria-label="Kembali" @click="$router.back()"><ArrowLeft /></button><h1 class="mt-7 text-3xl font-semibold tracking-[-.035em]">Edit memory</h1><textarea v-model="content" rows="8" class="surface mt-7 w-full resize-none rounded-3xl border border-line p-5 text-[16px] leading-7 outline-none focus:border-nemu-500" aria-label="Isi memory"/><button class="primary-button mt-5 w-full" :disabled="!content.trim()||loading" @click="save">{{loading?'Menyimpan…':'Simpan perubahan'}}</button></div></AppShell></template>
